// src/handlers/taskOps.ts (extended)
export async function refineTask(id: string, feedback: string, useAI: boolean, filePath: string = 'tasks.json') {
  const tasks = await loadAllTasks(filePath);
  const task = tasks.find(t => t.id === id);
  if (!task) throw new Error(`Task not found: ${id}`);
  let changes = feedback;
  if (useAI) {
    const { suggestedChanges } = await refineTaskAI(task, feedback); // From ai.ts
    changes = suggestedChanges;
  }
  task.history.push({ timestamp: new Date(), changes, feedback });
  task.description = task.description + ' (Refined: ' + changes + ')'; // Or AI-updated
  await Bun.write(`${filePath}.bak.${Date.now()}`, JSON.stringify(tasks)); // Backup
  await saveAllTasks(tasks, filePath);
  return task;
}

